<script>
  // Size each full-page frame to its content (the pages are same-origin).
  const frames = [...document.querySelectorAll('iframe[data-autoheight]')];
  setInterval(() => frames.forEach(f => {
    try {
      const d = f.contentDocument, foot = d && d.querySelector('footer');
      if (!foot) return;
      const h = Math.ceil(foot.getBoundingClientRect().bottom + d.defaultView.scrollY);
      if (h > 200 && Math.abs(h - f.offsetHeight) > 2) f.style.height = h + 'px';
    } catch (e) { /* opened from disk: keep default height */ }
  }), 800);
</script>
